class Solution {
public:
    bool checkPossibility(vector<int>& nums) {
        int n = nums.size();
        int modified = 0;
        for (int i = 0; i + 1 < n; i++) {
            if (nums[i] > nums[i + 1]) {
                if (modified) return false;
                modified = 1;
                if (i == 0 || nums[i - 1] <= nums[i + 1]) {
                    nums[i] = nums[i + 1];
                } else {
                    nums[i + 1] = nums[i];
                }
            }
        }
        return true;
    }
};
